package com.example.starter.rail.model;

/**
 * 封锁申请生命周期状态。
 * <ul>
 *   <li>PENDING：已提交，尚未审批；</li>
 *   <li>APPROVED：已审批，占用尚未开始；</li>
 *   <li>ACTIVE：已激活，区间正在实际占用；</li>
 *   <li>COMPLETED：已完成（终态）；</li>
 *   <li>CANCELLED：已取消（终态）；</li>
 *   <li>PREEMPTED：被更高优先级紧急申请抢占（终态）。</li>
 * </ul>
 */
public enum RequestStatus {
    PENDING,
    APPROVED,
    ACTIVE,
    COMPLETED,
    CANCELLED,
    PREEMPTED;

    /** 是否为不可再迁移的终态。 */
    public boolean isTerminal() {
        return this == COMPLETED || this == CANCELLED || this == PREEMPTED;
    }
}

package com.example.starter.rail.model;

import java.time.Instant;
import java.util.List;

/**
 * 封锁申请持久化对象。所有时刻均为 UTC（以 epoch 毫秒存储）。
 */
public class PossessionRequest {

    /** 申请唯一标识，由客户端生成。 */
    private String requestId;
    /** 半开时间窗开始（含），UTC epoch 毫秒。 */
    private long startTime;
    /** 半开时间窗结束（不含），UTC epoch 毫秒。 */
    private long endTime;
    /** 前安全缓冲，单位毫秒，非负。 */
    private long bufferBeforeMs;
    /** 后安全缓冲，单位毫秒，非负。 */
    private long bufferAfterMs;
    /** 优先级，数值越大越紧急。 */
    private int priority;
    /** 乐观版本号，每次合法状态迁移递增。 */
    private int version;
    /** 当前状态。 */
    private RequestStatus status;
    /** 关联区段，按提交顺序保存。 */
    private List<String> sectionIds = List.of();
    private long createdAt;
    private long updatedAt;

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }

    public long getStartTime() {
        return startTime;
    }

    public void setStartTime(long startTime) {
        this.startTime = startTime;
    }

    public long getEndTime() {
        return endTime;
    }

    public void setEndTime(long endTime) {
        this.endTime = endTime;
    }

    public long getBufferBeforeMs() {
        return bufferBeforeMs;
    }

    public void setBufferBeforeMs(long bufferBeforeMs) {
        this.bufferBeforeMs = bufferBeforeMs;
    }

    public long getBufferAfterMs() {
        return bufferAfterMs;
    }

    public void setBufferAfterMs(long bufferAfterMs) {
        this.bufferAfterMs = bufferAfterMs;
    }

    public int getPriority() {
        return priority;
    }

    public void setPriority(int priority) {
        this.priority = priority;
    }

    public int getVersion() {
        return version;
    }

    public void setVersion(int version) {
        this.version = version;
    }

    public RequestStatus getStatus() {
        return status;
    }

    public void setStatus(RequestStatus status) {
        this.status = status;
    }

    public List<String> getSectionIds() {
        return sectionIds;
    }

    public void setSectionIds(List<String> sectionIds) {
        this.sectionIds = sectionIds;
    }

    public long getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(long createdAt) {
        this.createdAt = createdAt;
    }

    public long getUpdatedAt() {
        return updatedAt;
    }

    public void setUpdatedAt(long updatedAt) {
        this.updatedAt = updatedAt;
    }

    /** 加缓冲后的实际占用窗开始（含）。 */
    public long bufferedStart() {
        return startTime - bufferBeforeMs;
    }

    /** 加缓冲后的实际占用窗结束（不含）。 */
    public long bufferedEnd() {
        return endTime + bufferAfterMs;
    }

    /** 序列化为快照时使用的业务时刻表示。 */
    public Instant startInstant() {
        return Instant.ofEpochMilli(startTime);
    }

    public Instant endInstant() {
        return Instant.ofEpochMilli(endTime);
    }
}

package com.example.starter.rail.model;

/**
 * 申请生命周期事件（只追加，不更新）。
 */
public class RequestEvent {

    private long id;
    /** 关联申请。 */
    private String requestId;
    /** 事件类型，如 APPROVED/ACTIVATED/COMPLETED/CANCELLED/PREEMPTED。 */
    private String eventType;
    /** 迁移前状态，首个事件为 null。 */
    private RequestStatus fromStatus;
    /** 迁移后状态。 */
    private RequestStatus toStatus;
    /** 客户端携带的业务时间，UTC epoch 毫秒。 */
    private Long businessTime;
    /** 服务端记录时刻，UTC epoch 毫秒。 */
    private long occurredAt;
    /** 操作请求指纹，幂等重放时不再追加事件。 */
    private String fingerprint;
    /** 附加明细（JSON 文本，可空）。 */
    private String detail;

    public long getId() {
        return id;
    }

    public void setId(long id) {
        this.id = id;
    }

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }

    public String getEventType() {
        return eventType;
    }

    public void setEventType(String eventType) {
        this.eventType = eventType;
    }

    public RequestStatus getFromStatus() {
        return fromStatus;
    }

    public void setFromStatus(RequestStatus fromStatus) {
        this.fromStatus = fromStatus;
    }

    public RequestStatus getToStatus() {
        return toStatus;
    }

    public void setToStatus(RequestStatus toStatus) {
        this.toStatus = toStatus;
    }

    public Long getBusinessTime() {
        return businessTime;
    }

    public void setBusinessTime(Long businessTime) {
        this.businessTime = businessTime;
    }

    public long getOccurredAt() {
        return occurredAt;
    }

    public void setOccurredAt(long occurredAt) {
        this.occurredAt = occurredAt;
    }

    public String getFingerprint() {
        return fingerprint;
    }

    public void setFingerprint(String fingerprint) {
        this.fingerprint = fingerprint;
    }

    public String getDetail() {
        return detail;
    }

    public void setDetail(String detail) {
        this.detail = detail;
    }
}

package com.example.starter.rail.model;

/**
 * 计划快照发布记录。发布后内容不可变，申请后续状态变化不得改写。
 */
public class PlanSnapshot {

    /** 快照唯一标识。 */
    private String snapshotId;
    /** 所属申请。 */
    private String requestId;
    /** 发布时的申请版本。 */
    private int versionAtPublish;
    /** 发布时的申请状态。 */
    private RequestStatus statusAtPublish;
    /** 不可变快照内容（JSON 文本）。 */
    private String content;
    /** 发布时刻，UTC epoch 毫秒。 */
    private long publishedAt;

    public String getSnapshotId() {
        return snapshotId;
    }

    public void setSnapshotId(String snapshotId) {
        this.snapshotId = snapshotId;
    }

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }

    public int getVersionAtPublish() {
        return versionAtPublish;
    }

    public void setVersionAtPublish(int versionAtPublish) {
        this.versionAtPublish = versionAtPublish;
    }

    public RequestStatus getStatusAtPublish() {
        return statusAtPublish;
    }

    public void setStatusAtPublish(RequestStatus statusAtPublish) {
        this.statusAtPublish = statusAtPublish;
    }

    public String getContent() {
        return content;
    }

    public void setContent(String content) {
        this.content = content;
    }

    public long getPublishedAt() {
        return publishedAt;
    }

    public void setPublishedAt(long publishedAt) {
        this.publishedAt = publishedAt;
    }
}

package com.example.starter.rail.model;

/**
 * 幂等记录：以客户端请求键为唯一键，保存首次请求的指纹与响应。
 */
public class IdempotencyRecord {

    /** 客户端请求键（唯一）。 */
    private String requestKey;
    /** 覆盖 requestId、expectedVersion、业务时间等参数的 SHA-256 指纹。 */
    private String fingerprint;
    /** 操作类型：ACTIVATE/COMPLETE/CANCEL。 */
    private String operation;
    /** 关联申请。 */
    private String requestId;
    /** 首次响应 HTTP 状态码。 */
    private int responseCode;
    /** 首次响应体（JSON 文本）。 */
    private String responseBody;
    private long createdAt;

    public String getRequestKey() {
        return requestKey;
    }

    public void setRequestKey(String requestKey) {
        this.requestKey = requestKey;
    }

    public String getFingerprint() {
        return fingerprint;
    }

    public void setFingerprint(String fingerprint) {
        this.fingerprint = fingerprint;
    }

    public String getOperation() {
        return operation;
    }

    public void setOperation(String operation) {
        this.operation = operation;
    }

    public String getRequestId() {
        return requestId;
    }

    public void setRequestId(String requestId) {
        this.requestId = requestId;
    }

    public int getResponseCode() {
        return responseCode;
    }

    public void setResponseCode(int responseCode) {
        this.responseCode = responseCode;
    }

    public String getResponseBody() {
        return responseBody;
    }

    public void setResponseBody(String responseBody) {
        this.responseBody = responseBody;
    }

    public long getCreatedAt() {
        return createdAt;
    }

    public void setCreatedAt(long createdAt) {
        this.createdAt = createdAt;
    }
}

package com.example.starter.rail.model;

/**
 * 单条区段冲突明细。按 sectionId、冲突窗口开始时间排序。
 */
public class ConflictDetail {

    /** 发生冲突的区段。 */
    private String sectionId;
    /** 与之冲突的已占用申请。 */
    private String otherRequestId;
    /** 冲突申请优先级，数值越大越紧急。 */
    private int otherPriority;
    /** 冲突申请状态（APPROVED/ACTIVE 等）。 */
    private RequestStatus otherStatus;
    /** 对方实际占用窗开始（含缓冲），UTC epoch 毫秒。 */
    private long otherBufferedStart;
    /** 对方实际占用窗结束（不含，含缓冲），UTC epoch 毫秒。 */
    private long otherBufferedEnd;
    /** 正长度重叠时长，单位毫秒；端点相接时为 0（不构成冲突）。 */
    private long overlapMs;

    public ConflictDetail() {
    }

    public ConflictDetail(String sectionId, String otherRequestId, int otherPriority,
                          RequestStatus otherStatus, long otherBufferedStart,
                          long otherBufferedEnd, long overlapMs) {
        this.sectionId = sectionId;
        this.otherRequestId = otherRequestId;
        this.otherPriority = otherPriority;
        this.otherStatus = otherStatus;
        this.otherBufferedStart = otherBufferedStart;
        this.otherBufferedEnd = otherBufferedEnd;
        this.overlapMs = overlapMs;
    }

    public String getSectionId() {
        return sectionId;
    }

    public void setSectionId(String sectionId) {
        this.sectionId = sectionId;
    }

    public String getOtherRequestId() {
        return otherRequestId;
    }

    public void setOtherRequestId(String otherRequestId) {
        this.otherRequestId = otherRequestId;
    }

    public int getOtherPriority() {
        return otherPriority;
    }

    public void setOtherPriority(int otherPriority) {
        this.otherPriority = otherPriority;
    }

    public RequestStatus getOtherStatus() {
        return otherStatus;
    }

    public void setOtherStatus(RequestStatus otherStatus) {
        this.otherStatus = otherStatus;
    }

    public long getOtherBufferedStart() {
        return otherBufferedStart;
    }

    public void setOtherBufferedStart(long otherBufferedStart) {
        this.otherBufferedStart = otherBufferedStart;
    }

    public long getOtherBufferedEnd() {
        return otherBufferedEnd;
    }

    public void setOtherBufferedEnd(long otherBufferedEnd) {
        this.otherBufferedEnd = otherBufferedEnd;
    }

    public long getOverlapMs() {
        return overlapMs;
    }

    public void setOverlapMs(long overlapMs) {
        this.overlapMs = overlapMs;
    }
}

