        RequestResponse replay = service.cancel("R1", body(1, 15_000), "KEY-CAN-1");
        assertThat(replay.status()).isEqualTo("CANCELLED");
        assertThat(repository.findEvents("R1"))
                .filteredOn(e -> e.getEventType().equals("CANCELLED"))
                .hasSize(1);
    }
}

